// Generated by tools/build-mods.mjs from coop/mods/*/ (mod.json + mod.js + icons). Do not edit: change the mod and rebuild.

// ---- trainer-growth 0.7.1 ----
if (CoopMods.manifest({"id":"trainer-growth","name":"训练家提升","version":"0.7.1","author":"chenjunjue","description":"捕捉宝可梦攒成长点：同一只只算第一次，按稀有度给点（传说和神话更多；野外捕捉、孵蛋、进化都算）。成长点在局外攒着，用来提升成长线：扭蛋机抽蛋的稀有度（被升过档的蛋，名字后面带个「+」）、局内队伍的运气、常驻能力值（自己的每一只宝可梦的攻击/防御/特攻/特防/速度永久加成，换宝可梦也还在），还有战后奖励：每场战斗的免费刷新次数、奖励栏位。进游戏后左上角的道具栏里有一个「训练家提升」道具，指一下就在右上角写着现在各项加了多少。单人和双人合作都能用。","default":"off","api":3,"modes":["solo","coop"]})) {
if (CoopMods.icons) CoopMods.icons("trainer-growth", {
 "boost": "data:image/png;base64,"
});
// 训练家提升（trainer-growth）0.7.1
//
// 规则：
//   - 获得一只宝可梦时给成长点（野外捕捉、孵蛋、进化出来的新形态都算）。同一只只算第一次：
//     这只在这台设备上已经算过点，就不再给。
//   - 给多少点看稀有度：神话 > 传说 > 准神 > 初始宝可梦（游戏里选它要几个点）> 普通野外宝可梦。
//     稀有度之间的差距比第一版小一些（神话是普通野外的 16 倍，原来是 20 倍）。
//   - 成长点是局外的（存在 localStorage，关掉游戏、换存档都还在），用来升级下面这些成长线。
//   - 成长线的价格越升越贵（基础价 × 1.35^当前等级）：前期一两级很便宜，后面越来越贵。
//   - 扭蛋机蛋的稀有度：每级让抽到的蛋有 12% 的概率升一档（普通→高级→超级→大师）。
//     被升过档的蛋，名字后面带个「+」（抽蛋结果页和背包里的蛋列表都能看到）。
//   - 局内运气：每级给队伍 +1 点运气（游戏里的运气值 0..14），战后奖励更容易出好东西。
//   - 常驻能力值：每级让玩家自己的每一只宝可梦的这项能力 +10%（像挥剑舞那样一直有效）：
//     升级、进化、换宝可梦都还在，敌人的不受影响。
//   - 免费刷新商店：每级让每场战斗结束后有 1 次免费刷新（游戏里那个「刷新商店」按钮）。
//   - 战后奖励栏位：每级让战后奖励的道具栏位 +1（默认 3 个）。
//   - 道具：左上角道具栏里的「训练家提升」道具，指一下就在右上角写着现在各项加了多少。
CoopMods.define('trainer-growth', function (api) {
  const M = api.meta(); // 局外数据：{ points, lines: {}, caught: {} }

  // ---- 稀有度 → 成长点 ----
  const POINTS = {
    mythical: 95, legendary: 65, subLegendary: 33,
    starterTop: 25, starterMid: 19, starterLow: 13, starterCheap: 9,
    wildBig: 9, wild: 6,
  };
  function pointsOf(r) {
    if (!r) return 0;
    if (r.mythical) return POINTS.mythical;
    if (r.legendary) return POINTS.legendary;
    if (r.subLegendary) return POINTS.subLegendary;
    if (r.starterCost > 0) {
      return r.starterCost >= 7 ? POINTS.starterTop : r.starterCost >= 5 ? POINTS.starterMid : r.starterCost >= 3 ? POINTS.starterLow : POINTS.starterCheap;
    }
    return r.baseTotal >= 600 ? POINTS.wildBig : POINTS.wild;
  }
  function rarityName(r) {
    if (!r) return '普通';
    if (r.mythical) return '神话';
    if (r.legendary) return '传说';
    if (r.subLegendary) return '准神';
    if (r.starterCost > 0) return '初始宝可梦（' + r.starterCost + ' 点）';
    return '野外';
  }

  // ---- 获得宝可梦：第一次才算点 ----
  // 野外捕捉、孵蛋、进化出来的新形态都算「获得」（扩展照游戏自己的规矩判断）。
  // 是不是第一次由这个 mod 自己记（局外数据里的 caught），不靠游戏的图鉴：
  // 图鉴里早就有的（装这个 mod 之前抓的）也会给一次点，之后再抓同一只就不给了。
  const HOW = { catch: '捕捉到', egg: '孵出了', evolution: '进化得到了' };
  api.on('pokemonCaught', ev => {
    if (!ev) return;
    const key = String(ev.speciesId);
    if (M.caught[key]) return; // 这台设备上已经算过这只了
    const points = pointsOf(ev.rarity);
    if (!(points > 0)) return;
    M.caught[key] = points;
    M.points += points;
    M.total = (Number(M.total) || 0) + points;
    api.metaSave();
    const how = HOW[ev.kind] || '获得了';
    api.log(how + ' ' + ev.name + '（' + rarityName(ev.rarity) + '）：+' + points + ' 成长点，一共 ' + Math.floor(M.points) + ' 点');
  });

  // ---- 成长线 ----
  const GACHA_STEP = 0.12; // 每级：蛋升一档的概率
  const STAT_STEP = 0.10;  // 每级：这项能力 +10%（对玩家自己的每一只宝可梦）
  const STAT_MAX = 5;      // 每项能力最多几级（5 级 = +50%）
  const STAT_COST = 90;    // 能力值每级多少点
  // 价格：越升越贵。基础价 × 1.35^当前等级，取整到 5 的倍数。
  // 早期一两级很便宜（很快能尝到甜头），后面越来越贵，是真的要下决心。
  const PRICE_STEP = 1.35;
  const price = (base, lv) => Math.max(0, Math.round(base * Math.pow(PRICE_STEP, lv) / 5) * 5);
  // 能力值：key 是游戏里的名字（atk/def/spatk/spdef/spd），id 是成长线的名字
  const STATS = [
    { id: 'statAtk', key: 'atk', name: '攻击', short: '攻' },
    { id: 'statDef', key: 'def', name: '防御', short: '防' },
    { id: 'statSpAtk', key: 'spatk', name: '特攻', short: '特攻' },
    { id: 'statSpDef', key: 'spdef', name: '特防', short: '特防' },
    { id: 'statSpd', key: 'spd', name: '速度', short: '速' },
  ];
  const LINES = [
    {
      id: 'gacha', name: '扭蛋机蛋的稀有度', short: '蛋的稀有度', max: 5, cost: lv => price(150, lv),
      desc: lv => '抽到的蛋有 ' + Math.round(GACHA_STEP * lv * 100) + '% 的概率升一档（普通→高级→超级→大师）。',
      brief: lv => '升档 +' + Math.round(GACHA_STEP * lv * 100) + '%',
    },
    {
      id: 'luck', name: '局内运气', short: '运气', max: 5, cost: lv => price(120, lv),
      desc: lv => '队伍的运气 +' + lv + '（游戏里的运气值 0..14）。战后奖励更容易出好东西，野怪也更容易出稀有种。',
      brief: lv => '+' + lv,
    },
    {
      // 2 次就够把战后奖励刷到想要的了，再多收益很小，所以上限压到 2 级、价格提到和别的一样
      id: 'freeReroll', name: '免费刷新商店', short: '免费刷新', max: 2, cost: lv => price(150, lv),
      desc: lv => '每场战斗结束后有 ' + lv + ' 次免费刷新（战后奖励界面左下角那个「刷新商店」）。',
      brief: lv => '每场 ×' + lv,
    },
    {
      // 栏位是最值钱的一条（奖励池直接变大），所以不再是最便宜的那条
      id: 'rewardSlots', name: '战后奖励栏位', short: '奖励栏位', max: 5, cost: lv => price(150, lv),
      desc: lv => '战后奖励的道具栏位 +' + lv + '（默认 3 个，可以挑的更多）。',
      brief: lv => '+' + lv + ' 个',
    },
  ].concat(STATS.map(s => ({
    id: s.id, name: '常驻' + s.name, short: '常驻' + s.name, max: STAT_MAX, cost: lv => price(STAT_COST, lv),
    desc: lv => '自己的每只宝可梦' + s.name + ' +' + Math.round(STAT_STEP * lv * 100) + '%（升级、进化、换宝可梦都还在，敌人不受影响）。',
    brief: lv => '+' + Math.round(STAT_STEP * lv * 100) + '%',
  })));
  const level = id => {
    const l = LINES.find(x => x.id === id);
    if (!l) return 0;
    return Math.max(0, Math.min(l.max, Math.floor(Number(M.lines[id]) || 0)));
  };

  // ---- 道具：训练家提升 ----
  // 一个真的道具（被动增益，图标是自己画的 32x32 像素画）：
  // 它会像游戏自己的道具一样出现在左上角的道具栏里，指上去/点一下，右上角就出现说明，
  // 里面写着现在各项成长线加了多少（游戏自己的道具说明面板，和别的道具一模一样）。
  api.item({
    id: 'boost',
    name: '训练家提升',
    description: '把捕捉宝可梦攒下来的成长点变成永久加成：扭蛋机抽蛋的稀有度、局内运气、每场战斗的免费刷新、战后奖励的栏位，还有常驻的攻击/防御/特攻/特防/速度。说明里写着现在每一项加了多少。',
    tier: 'COMMON',
    weight: 0, // 一直待在队伍背包里，不作为随机奖励出现
    kind: 'passive',
    max: 1,
    icon: 'boost',
  });

  // 道具说明面板里写什么（这个 mod 最清楚自己每条成长线是什么）
  api.on('itemInfo', () => {
    const out = [];
    for (const l of LINES) {
      const lv = level(l.id);
      if (lv <= 0) continue;
      out.push((l.short || l.name) + ' Lv' + lv + '：' + (typeof l.brief === 'function' ? l.brief(lv) : ''));
    }
    if (!out.length) out.push('还没有升级任何成长线。');
    const n = Object.keys(M.caught || {}).length;
    out.push('成长点 ' + Math.floor(M.points) + ' · 已捕捉 ' + n + ' 种');
    return out.join('\n');
  });

  // 面板顶上那一行：现在这些成长线加在一起是什么效果
  function summary() {
    const parts = [];
    const luck = level('luck');
    if (luck > 0) parts.push('运气 +' + luck);
    const gacha = level('gacha');
    if (gacha > 0) parts.push('抽蛋升档 +' + Math.round(GACHA_STEP * gacha * 100) + '%');
    const freeReroll = level('freeReroll');
    if (freeReroll > 0) parts.push('免费刷新 ×' + freeReroll);
    const rewardSlots = level('rewardSlots');
    if (rewardSlots > 0) parts.push('奖励栏位 +' + rewardSlots);
    for (const s of STATS) {
      const lv = level(s.id);
      if (lv > 0) parts.push(s.name + ' +' + Math.round(STAT_STEP * lv * 100) + '%');
    }
    return parts.length ? parts.join(' · ') : '还没有升级任何成长线';
  }

  // 面板上再写一行：捕捉进度（图鉴一共有多少种是游戏自己的数据，这里现问）
  function note() {
    const n = Object.keys(M.caught || {}).length;
    const total = api.dexTotal();
    const head = total
      ? '已捕捉 ' + n + ' / ' + total + ' 种（' + Math.round((n / total) * 100) + '%）'
      : '已捕捉 ' + n + ' 种';
    let out = head + ' · 累计 ' + Math.floor(M.total || 0) + ' 点';
    // 扭蛋机：上次抽了几个蛋、其中几个被我们的加成升了档
    const st = api.runState();
    const lastN = Number(st.gachaN) || 0;
    if (lastN > 0) {
      out += ' · 上次扭蛋机 ' + lastN + ' 个蛋里 ' + (Number(st.gachaUp) || 0) + ' 个被加成升档';
    }
    const allN = Number(st.gachaTotal) || 0;
    if (allN > 0) {
      out += '（这一局共抽了 ' + allN + ' 个，' + (Number(st.gachaTotalUp) || 0) + ' 个升了档）';
    }
    return out;
  }

  api.metaPanel({
    title: '成长点',
    summary,
    note,
    lines: LINES.map(l => ({ id: l.id, name: l.name, max: l.max, cost: l.cost, desc: l.desc })),
    // 升级/退款不再往游戏的消息栏里弹东西了：面板上已经写着「刚升级：xxx → Lv2」。
  });

  // ---- 效果 1：局内运气 ----
  // 游戏把队伍的运气加到 0..14：奖励选项的稀有度、奖励画面上的字母、野外宝可梦的稀有度都用它。
  api.on('teamLuck', ev => {
    const lv = level('luck');
    return lv > 0 ? lv : undefined;
  });

  // ---- 效果 2：扭蛋机蛋的稀有度 ----
  api.on('gachaEggTier', ev => {
    const lv = level('gacha');
    if (!(lv > 0) || ev.tier >= 3) return;
    const p = GACHA_STEP * lv;
    const roll = api.rng('trainer-growth:gacha:' + ev.n + ':' + ev.tier)();
    return roll < p ? ev.tier + 1 : undefined;
  });

  // ---- 扭蛋机的账：抽了多少个蛋、其中几个被我们的加成升了档 ----
  // 记在这一局的存档里（api.runState），面板上能看到。
  const TIER_ZH = ['普通', '高级', '超级', '大师']; // 蛋的稀有度（EggTier）
  api.on('gachaPull', ev => {
    const st = api.runState();
    const n = ev && ev.count > 0 ? Math.floor(ev.count) : 0;
    st.gachaN = n;        // 上一批抽了几个
    st.gachaUp = 0;       // 这一批里有几个被升了档
    st.gachaTotal = (Number(st.gachaTotal) || 0) + n; // 这一局一共抽了几个
  });
  api.on('gachaEggBoosted', ev => {
    if (!ev) return;
    const st = api.runState();
    st.gachaUp = (Number(st.gachaUp) || 0) + 1;
    st.gachaTotalUp = (Number(st.gachaTotalUp) || 0) + 1;
    api.log('扭蛋机：有一只蛋被加成升了一档（' + (TIER_ZH[ev.tier] || '?') + ' → ' + (TIER_ZH[ev.newTier] || '?') + '）');
  });
  // 蛋的名字后面要不要加个「+」：这一局被我们升过档的蛋，编号记下来，
  // 这样重开游戏（蛋是从存档里读回来的）也还标得出来。
  api.on('gachaEggMark', ev => {
    if (!ev) return;
    const st = api.runState();
    if (!st.boostedEggs || typeof st.boostedEggs !== 'object') st.boostedEggs = {};
    const key = ev.id == null ? '' : String(ev.id);
    if (ev.boosted) {
      if (key) st.boostedEggs[key] = 1;
      return true; // 这只蛋刚被升了档：标上
    }
    return !!(key && st.boostedEggs[key]); // 存档里记着的：也标上
  });

  // ---- 效果 3：常驻能力值 ----
  // 扩展在游戏算完能力值之后问一遍：往 ev.bonus 里写比例，它会加到这只宝可梦的数值上。
  // 每一只玩家自己的宝可梦都算（所以换宝可梦也照样有），敌人的不算。
  api.on('pokemonStatBonus', ev => {
    if (!ev || !ev.bonus) return;
    for (const s of STATS) {
      const lv = level(s.id);
      if (lv > 0) ev.bonus[s.key] = (Number(ev.bonus[s.key]) || 0) + lv * STAT_STEP;
    }
  });

  // ---- 效果 4：免费刷新商店 ----
  // 战后奖励界面左下角那个「刷新商店」按钮（重掷战后奖励）本来要钱，
  // 这里给的成长线让它每场战斗有几次是免费的：换一场战斗（层数变了）重新给满。
  // 次数记在这一局的存档里（api.runState()），关掉游戏也还在。
  function freeRerollLeft() {
    const lv = level('freeReroll');
    if (!(lv > 0)) return 0;
    const st = api.runState();
    const wave = api.battle.wave();
    if (st.frWave !== wave) { st.frWave = wave; st.frUsed = 0; } // 新的一场战斗，重新给次数
    return Math.max(0, lv - (Number(st.frUsed) || 0));
  }
  api.on('rerollCost', ev => {
    if (!ev || !(ev.cost > 0)) return;
    const left = freeRerollLeft();
    if (left > 0) return { cost: 0, label: '免费×' + left }; // 按钮下面会写「免费×N」
  });
  api.on('rerolled', ev => {
    if (!ev || !ev.free) return; // 只有免费的刷新才用掉一次
    freeRerollLeft();
    const st = api.runState();
    st.frUsed = (Number(st.frUsed) || 0) + 1;
  });

  // ---- 效果 5：战后奖励的栏位 ----
  // 常规战斗结束后那排道具（默认 3 个）能多几个，可以挑的更多。
  api.on('rewardCount', ev => {
    const lv = level('rewardSlots');
    if (lv > 0 && ev) return ev.count + lv;
  });
});
}

